vec4 color(vec4 inputColor) {
    vec4 colors[16] = vec4[16](
        vec4(0.33, 0.42, 0.18, 1.0), // Olive green
        vec4(0.40, 0.26, 0.13, 1.0), // Brown
        vec4(0.55, 0.55, 0.45, 1.0), // Khaki
        vec4(0.36, 0.38, 0.20, 1.0), // Dark olive
        vec4(0.29, 0.35, 0.13, 1.0), // Forest green
        vec4(0.45, 0.39, 0.23, 1.0), // Tan
        vec4(0.21, 0.27, 0.14, 1.0), // Dark green
        vec4(0.44, 0.40, 0.25, 1.0), // Earth brown
        vec4(0.38, 0.49, 0.19, 1.0), // Moss green
        vec4(0.50, 0.46, 0.33, 1.0), // Sand
        vec4(0.25, 0.30, 0.12, 1.0), // Deep olive
        vec4(0.48, 0.36, 0.24, 1.0), // Mud brown
        vec4(0.41, 0.36, 0.18, 1.0), // Mustard olive
        vec4(0.52, 0.50, 0.35, 1.0), // Light tan
        vec4(0.32, 0.44, 0.20, 1.0), // Medium green
        vec4(0.42, 0.34, 0.22, 1.0)  // Bark brown
    );

    float minDistance = distance(inputColor, colors[0]);
    vec4 closestColor = colors[0];

    for (int i = 1; i < 16; i++) {
        float currentDistance = distance(inputColor, colors[i]);
        if (currentDistance < minDistance) {
            minDistance = currentDistance;
            closestColor = colors[i];
        }
    }

    return closestColor;
}
vec2 F(vec2 U) {
    float k = 2.;
    U +=  k*noise(2.*U*ei(1.5)).xy;
    U +=  k*noise(.5*U*ei(-.5)).xy;
    U +=  k*noise(.25*U*ei(1.2)).xy;

    U = floor(U*vec2(4.,1)*ei(1.5))*ei(-1.5)/vec2(4,1);
    U = floor(U/vec2(10.,2)*ei(.5))*ei(-.5)*vec2(10,2);

    U -=  k*noise(.25*U*ei(1.2)).xy;
    U -=  k*noise(.5*U*ei(-.5)).xy;
    U -=  k*noise(2.*U*ei(1.5)).xy;
    return U;
}

Main {
    Q = vec4(0);
    for (float x = -2.;x <= 2.; x++) 
    for (float y = -2.;y <= 2.; y++) {
        vec2 u = U+vec2(x,y)/4.;
        u -= .5*R;
        u *= .51-.49*cos(.25*iTime);
        u += .5*R;
        vec4 q = pow(B(F(2.*u)*.5),vec4(2));
        Q += 1./25.*mix(q,color(q),.8);
    }
}

#define R iResolution.xy
#define Main void mainImage(out vec4 Q, in vec2 U)
#define A(U) texture(iChannel0,(U)/R)
#define B(U) texture(iChannel1,(U)/R)
#define C(U) texture(iChannel2,(U)/R)

#define ei(a) mat2(cos(a),sin(a),-sin(a),cos(a))
vec4 hash44(vec4 p4)
{
	p4 = fract(p4  * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+33.33);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);
}
vec4 noise (vec2 U) {
    vec2 f = floor(U);
    vec2 c = ceil(U);
    vec4 _00 = hash44(vec4(f,f));
    vec4 _01 = hash44(vec4(f.x,c.y,f.x,c.y));
    vec4 _10 = hash44(vec4(c.x,f.y,c.x,f.y));
    vec4 _11 = hash44(vec4(c,c));
    vec4 _0 = mix(_00,_01,fract(U.y));
    vec4 _1 = mix(_10,_11,fract(U.y));
    return mix(_0,_1,fract(U.x))*2.-1.;
}
vec4 fbm (vec2 U) {
    mat2 m = ei(.5);
    vec4 o = vec4(0);
    for (float i = 0.; i < 105.; i++) {
        U *= 1.2*m;
        o += (noise(U+100.))*exp2(-.5*i);
    }
    return o;
}
